<template>
 <div class="info-backdrop quest-backdrop" @mousedown.self="$emit('close')" @keydown.stop @keyup.stop>
  <section ref="panel" class="quest-journal" role="dialog" aria-modal="true" aria-labelledby="quest-journal-title" tabindex="-1" @keydown.esc.prevent="$emit('close')" @keydown.tab="trap" data-quest-journal>
   <header class="quest-header">
    <span class="quest-book" aria-hidden="true"><journal-icon name="progress"/></span>
    <div><p>{{ english?'EXPLORER’S JOURNAL':'CARNET D’EXPLORATION' }}</p><h2 id="quest-journal-title">{{ english?'Objectives and quests':'Objectifs et quêtes' }}</h2></div>
    <button class="quest-close" @click="$emit('close')" :aria-label="english?'Close journal':'Fermer le journal'">×</button>
   </header>
   <div class="quest-overview"><span><b>{{ completedCount }}</b> {{ english?'steps completed':'étapes accomplies' }}</span><span><i aria-hidden="true"/>{{ activeCount }} {{ english?'in progress':'en cours' }}</span></div>
   <div class="quest-filters" role="tablist" :aria-label="english?'Quest status':'État des quêtes'">
    <button v-for="tab in tabs" :id="'quest-tab-'+tab.key" :key="tab.key" role="tab" :aria-selected="filter===tab.key?'true':'false'" aria-controls="quest-list" :tabindex="filter===tab.key?0:-1" @click="selectTab(tab.key)" @keydown.left.prevent="nextTab(-1)" @keydown.right.prevent="nextTab(1)" @keydown.home.prevent="selectTab('active',true)" @keydown.end.prevent="selectTab('all',true)">{{ tab.title }}<small>{{ countFor(tab.key) }}</small></button>
   </div>
   <div id="quest-list" class="quest-scroll" role="tabpanel" :aria-labelledby="'quest-tab-'+filter" tabindex="0">
    <p v-if="loading||!journal" class="quest-empty" role="status">{{ english?'Updating your journal…':'Mise à jour du carnet…' }}</p>
    <template v-else>
     <section v-for="group in groups" :key="group.key" class="quest-chapter" :aria-label="group.title">
      <div class="quest-chapter-heading"><span>{{ group.key==='story'?'01':'02' }}</span><h3>{{ group.title }}</h3><i/></div>
      <ol class="quest-timeline">
       <li v-for="quest in group.entries" :key="quest.key" class="quest-row" :class="{'is-completed':quest.status==='completed','is-new':newKeys.includes(quest.key)}" :data-quest-key="quest.key" :data-quest-status="quest.status">
        <span class="quest-marker" aria-hidden="true"><svg v-if="quest.status==='completed'" viewBox="0 0 20 20"><path d="m4 10 4 4 8-8"/></svg><i v-else/></span>
        <article class="quest-page">
         <button class="quest-toggle" :aria-expanded="expanded===quest.key?'true':'false'" :aria-controls="'quest-detail-'+quest.key" @click="expanded=expanded===quest.key?null:quest.key">
          <span class="quest-title"><small>{{ quest.status==='completed'?(english?'COMPLETED':'TERMINÉE'):(english?'TO DO':'À ACCOMPLIR') }}</small><strong>{{ quest.title }}</strong></span>
          <span v-if="newKeys.includes(quest.key)" class="quest-new">{{ english?'New':'Nouveau' }}</span><svg class="quest-chevron" :class="{'is-open':expanded===quest.key}" viewBox="0 0 20 20" aria-hidden="true"><path d="m5 8 5 5 5-5"/></svg>
         </button>
         <div v-show="expanded===quest.key" :id="'quest-detail-'+quest.key" class="quest-detail">
          <p>{{ quest.description }}</p>
          <div v-if="quest.target>1" class="quest-counter"><span>{{ english?'Rooms completed':'Salles terminées' }} <b>{{ quest.progress }} / {{ quest.target }}</b></span><div role="progressbar" :aria-label="quest.title" :aria-valuenow="quest.progress" :aria-valuemax="quest.target" aria-valuemin="0"><i :style="{width:percent(quest)+'%'}"/></div></div>
          <p v-if="quest.destination" class="quest-destination"><journal-icon name="minimap"/><span>{{ quest.destination }}</span><button v-if="quest.map" class="quest-map-button" :data-quest-map="quest.map" @click="$emit('locate',quest.map)">{{ english?'View on map':'Voir sur la carte' }}</button></p>
          <p v-if="quest.status==='completed'" class="quest-done-note"><svg viewBox="0 0 20 20" aria-hidden="true"><path d="m4 10 4 4 8-8"/></svg>{{ english?'Objective completed. Your journal has been updated.':'Objectif accompli. Cette étape est inscrite dans ton carnet.' }}</p>
         </div>
        </article>
       </li>
      </ol>
     </section>
     <div v-if="!groups.length" class="quest-empty"><journal-icon :name="filter==='completed'?'progress':'minimap'"/><h3>{{ filter==='completed'?(english?'Your story is beginning':'Ton histoire commence'):(english?'No objective in progress':'Aucun objectif en cours') }}</h3><p>{{ filter==='completed'?(english?'Your completed steps will be recorded here.':'Les étapes que tu accomplis seront conservées ici.'):(english?'Keep exploring and talk to the people you meet.':'Continue à explorer et à parler aux personnes que tu rencontres.') }}</p></div>
     <adventure-guide v-if="filter==='active'" help-only :language="language"/>
    </template>
   </div>
   <footer class="quest-footer"><span><svg viewBox="0 0 20 20" aria-hidden="true"><path d="m4 10 4 4 8-8"/></svg>{{ readBusy?(english?'Saving…':'Enregistrement…'):(english?'Progress saved automatically':'Progression enregistrée automatiquement') }}</span><p v-if="readError" role="alert">{{ readError }} <button @click="readNew">{{ english?'Retry':'Réessayer' }}</button></p></footer>
  </section>
 </div>
</template>
<script>
import JournalIcon from './JournalIcon.vue';
import AdventureGuide from './AdventureGuide.vue';
export default {
 name:'QuestJournal',components:{JournalIcon,AdventureGuide},
 props:{journal:Object,loading:Boolean,readBusy:Boolean,readError:String,language:{type:String,default:'fr'}},
 data:()=>({filter:'active',expanded:null,newKeys:[]}),
 computed:{
  english(){return this.language==='en';},
  entries(){return [...(this.journal?.entries||[])].sort((a,b)=>a.order-b.order);},
  activeCount(){return this.entries.filter(q=>q.status==='active').length;},
  completedCount(){return this.entries.filter(q=>q.status==='completed').length;},
  unreadKeys(){return this.entries.filter(q=>q.unread).map(q=>q.key);},
  tabs(){return [{key:'active',title:this.english?'In progress':'En cours'},{key:'completed',title:this.english?'Completed':'Terminées'},{key:'all',title:this.english?'All':'Tout le carnet'}];},
  groups(){return [{key:'story',title:this.english?'Your story':'Ton histoire'},{key:'afterstory',title:this.english?'Beyond the story':'Après l’histoire'}].map(g=>({...g,entries:this.entries.filter(q=>q.section===g.key&&(this.filter==='all'||q.status===this.filter))})).filter(g=>g.entries.length);}
 },
 watch:{unreadKeys(){this.rememberNew();},loading(value){if(!value)this.rememberNew();}},
 mounted(){this._previous=document.activeElement;this.$refs.panel.focus({preventScroll:true});this.expanded=this.entries.find(q=>q.status==='active')?.key||null;this.rememberNew();},
 beforeDestroy(){if(this._previous?.isConnected)this._previous.focus({preventScroll:true});},
 methods:{
  rememberNew(){if(this.loading)return;this.newKeys=[...new Set([...this.newKeys,...this.unreadKeys])];if(!this.expanded)this.expanded=this.entries.find(q=>q.status==='active')?.key||null;if(this.unreadKeys.length)this.$emit('read',this.unreadKeys);},
  readNew(){if(this.unreadKeys.length)this.$emit('read',this.unreadKeys);},
  countFor(key){return key==='active'?this.activeCount:key==='completed'?this.completedCount:this.entries.length;},
  percent(q){return Math.max(0,Math.min(100,100*q.progress/Math.max(1,q.target)));},
  selectTab(key,focus=false){this.filter=key;this.expanded=this.entries.find(q=>key==='all'||q.status===key)?.key||null;if(focus)this.$nextTick(()=>this.$el.querySelector('#quest-tab-'+key)?.focus());},
  nextTab(step){const i=this.tabs.findIndex(t=>t.key===this.filter);this.selectTab(this.tabs[(i+step+this.tabs.length)%this.tabs.length].key,true);},
  trap(e){const nodes=[...this.$refs.panel.querySelectorAll('button:not(:disabled),[tabindex="0"]')].filter(n=>n.getClientRects().length),first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&[first,this.$refs.panel].includes(document.activeElement)){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}
 }
};
</script>
<style scoped>
.quest-destination{flex-wrap:wrap}.quest-map-button{margin-left:auto;min-height:40px;border:1px solid var(--journal-border);border-radius:7px;background:var(--journal-selected);color:var(--journal-heading);font:600 11px var(--journal-font);padding:8px 10px;cursor:pointer}

.quest-backdrop{display:flex;align-items:center;justify-content:center;color:var(--journal-ink);font:14px/1.5 var(--journal-font);box-sizing:border-box}.quest-journal{display:flex;flex-direction:column;width:min(820px,100%);max-height:calc(100dvh - 48px);min-height:0;overflow:hidden;background:var(--journal-paper);border:1px solid var(--journal-border);border-radius:15px;box-shadow:var(--journal-shadow);text-align:left}.quest-journal *{box-sizing:border-box}button{font:inherit;color:inherit;cursor:pointer}button:focus-visible,[tabindex]:focus-visible{outline:2px solid var(--journal-accent);outline-offset:3px}.quest-header{display:flex;align-items:center;gap:13px;padding:22px 26px;border-bottom:1px solid var(--journal-border);background:var(--journal-card);flex:none}.quest-header>div{flex:1;min-width:0}.quest-header p{font-size:9px;letter-spacing:.16em;color:var(--journal-muted);margin:0 0 3px}.quest-header h2{font:600 26px/1.2 Georgia,serif;color:var(--journal-heading);margin:0}.quest-book{display:grid;place-items:center;width:44px;height:48px;flex:none;border:1px solid var(--journal-border);border-radius:7px 13px 13px 7px;background:var(--journal-selected);color:var(--journal-accent);box-shadow:inset 4px 0 0 var(--journal-accent)}.quest-book .journal-icon{width:24px;height:24px}.quest-close{display:grid;place-items:center;flex:none;width:40px;height:40px;border:1px solid var(--journal-border);border-radius:50%;background:transparent;font-size:24px;line-height:1}.quest-close:hover{background:var(--journal-selected)}.quest-overview{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:12px 26px;background:var(--journal-soft);border-bottom:1px solid var(--journal-border);font-size:12px;color:var(--journal-muted);font-variant-numeric:tabular-nums}.quest-overview b{font-size:18px;font-weight:600;color:var(--journal-heading);margin-right:3px}.quest-overview>span:last-child{display:flex;align-items:center;gap:6px}.quest-overview i{width:6px;height:6px;border-radius:50%;background:var(--journal-accent)}.quest-filters{display:flex;gap:8px;padding:15px 26px 12px;flex:none}.quest-filters button{display:flex;align-items:center;justify-content:center;gap:9px;min-height:42px;padding:8px 14px;border:1px solid var(--journal-border);border-radius:7px;background:transparent;font-size:12px}.quest-filters button[aria-selected=true]{background:var(--journal-selected);border-color:var(--journal-accent);color:var(--journal-heading);font-weight:600}.quest-filters small{font-size:10px;font-variant-numeric:tabular-nums;opacity:.75}.quest-scroll{overflow:auto;min-height:150px;overscroll-behavior:contain;scrollbar-gutter:stable;padding:5px 26px 24px;flex:1}.quest-chapter+.quest-chapter{margin-top:26px}.quest-chapter-heading{display:flex;align-items:center;gap:10px;margin:7px 0 15px}.quest-chapter-heading>span{font-size:10px;font-weight:600;color:var(--journal-accent);font-variant-numeric:tabular-nums}.quest-chapter-heading h3{margin:0;color:var(--journal-heading);font-size:13px;white-space:nowrap}.quest-chapter-heading>i{height:1px;background:var(--journal-border);flex:1}.quest-timeline{list-style:none;padding:0;margin:0}.quest-row{display:grid;grid-template-columns:22px minmax(0,1fr);gap:12px;position:relative;padding-bottom:13px}.quest-row:not(:last-child):before{content:'';position:absolute;left:10px;top:31px;bottom:-4px;width:1px;background:var(--journal-border)}.quest-marker{display:grid;place-items:center;align-self:start;margin-top:16px;width:22px;height:22px;border:1px solid var(--journal-accent);border-radius:50%;background:var(--journal-paper);color:var(--journal-accent);z-index:1}.quest-marker i{width:7px;height:7px;border-radius:50%;background:currentColor}.quest-marker svg,.quest-done-note svg,.quest-footer svg{width:15px;height:15px;fill:none;stroke:currentColor;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round}.quest-page{border:1px solid var(--journal-border);border-radius:9px;background:var(--journal-card);overflow:hidden}.is-new .quest-page{border-color:var(--journal-accent)}.quest-toggle{display:flex;align-items:center;gap:12px;padding:14px 17px;width:100%;border:0;background:transparent;text-align:left;min-height:64px}.quest-title{flex:1;min-width:0}.quest-title strong{display:block;font-size:15px;line-height:1.35;color:var(--journal-heading);font-weight:600;overflow-wrap:anywhere}.quest-title>small{display:block;font-size:8px;letter-spacing:.12em;margin-bottom:4px;color:var(--journal-accent)}.is-completed .quest-title>small{color:var(--journal-muted)}.is-completed .quest-marker{color:#68937a;border-color:#68937a}.is-completed .quest-toggle{min-height:58px;padding-block:11px}.is-completed .quest-title strong{font-size:13px}.quest-new{border:1px solid #c89954;border-radius:5px;background:#f2bc5826;color:var(--journal-heading);padding:3px 7px;font-size:10px;white-space:nowrap}.quest-chevron{width:18px;height:18px;flex:none;fill:none;stroke:var(--journal-muted);stroke-width:1.5;transition:transform .18s}.quest-chevron.is-open{transform:rotate(180deg)}.quest-detail{padding:0 17px 16px}.quest-detail>p:first-child{margin:0 0 14px;font-size:13px;line-height:1.65;color:var(--journal-ink)}.quest-destination{display:flex;align-items:center;gap:8px;margin:0;padding-top:12px;border-top:1px solid var(--journal-border);color:var(--journal-accent);font-size:12px}.quest-destination .journal-icon{width:17px;height:17px;flex:none}.quest-counter{margin:15px 0}.quest-counter>span{display:flex;justify-content:space-between;font-size:11px;color:var(--journal-muted);margin-bottom:7px}.quest-counter b{color:var(--journal-heading)}.quest-counter>div{height:6px;background:var(--journal-border);border-radius:4px;overflow:hidden}.quest-counter i{display:block;height:100%;background:var(--journal-accent);transition:width .25s}.quest-done-note{display:flex;align-items:center;gap:6px;color:var(--journal-muted);font-size:11px;margin:12px 0 0}.quest-done-note svg{color:#68937a;flex:none}.quest-footer{flex:none;padding:12px 26px;border-top:1px solid var(--journal-border);background:var(--journal-soft);font-size:10px;color:var(--journal-muted)}.quest-footer>span{display:flex;align-items:center;gap:6px}.quest-footer p{font-size:12px;margin:7px 0 0;color:var(--journal-danger)}.quest-footer p button{border:1px solid var(--journal-border);border-radius:5px;background:var(--journal-card);min-height:36px;margin-left:8px}.quest-empty{text-align:center;padding:30px 18px;color:var(--journal-muted)}.quest-empty>.journal-icon{width:30px;height:30px;opacity:.7}.quest-empty h3{font-size:16px;color:var(--journal-heading)}.quest-empty p{font-size:13px;line-height:1.6}
@media(max-width:600px){.quest-journal{max-height:calc(100dvh - 16px);border-radius:11px;width:100%}.quest-header{padding:16px 14px;gap:10px}.quest-book{width:34px;height:41px}.quest-book .journal-icon{width:21px;height:21px}.quest-header h2{font-size:21px}.quest-header p{font-size:7px;letter-spacing:.12em}.quest-close{width:36px;height:36px}.quest-overview{padding:10px 15px;font-size:10px}.quest-overview b{font-size:16px}.quest-filters{padding:12px 14px 10px;gap:6px}.quest-filters button{flex:1;padding:8px 6px;gap:5px;font-size:11px}.quest-filters small{font-size:9px}.quest-scroll{padding:3px 13px 16px}.quest-row{gap:8px;grid-template-columns:19px minmax(0,1fr)}.quest-row:before{left:9px!important}.quest-marker{width:19px;height:19px}.quest-toggle{padding:13px 12px;gap:7px}.quest-title strong{font-size:14px}.quest-new{font-size:8px;padding:3px 5px}.quest-chevron{width:14px;height:14px}.quest-detail{padding:0 12px 14px}.quest-detail>p:first-child{font-size:12px}.quest-destination{font-size:11px}.quest-footer{padding:11px 15px}.quest-chapter-heading{margin-bottom:12px;gap:8px}.quest-chapter-heading h3{font-size:12px}}
@media(max-height:500px){.quest-header{padding-block:10px}.quest-overview{padding-block:6px}.quest-filters{padding-top:8px;padding-bottom:8px}.quest-scroll{min-height:0}.quest-footer{padding-block:7px}}@media(prefers-reduced-motion:reduce){*{transition:none!important}}
</style>
